"""Safe deletion of downloaded temporary video files."""

from __future__ import annotations

import re
from pathlib import Path

# Name instapuller generates when not keeping the video: <code>_<8 hex>.<ext>
_GENERATED_NAME_RE = re.compile(r"[A-Za-z0-9_-]{5,}_[0-9a-f]{8}\.(?:mp4|mov|webm|mkv|m4v)", re.I)


def cleanup_file(path: Path | str) -> bool:
    """Delete a temporary video file generated by instapuller.

    Return True if deleted, False if it did not exist. Raise ValueError for any other file name.
    """
    p = Path(path)
    if p.is_dir():
        raise IsADirectoryError("cleanup_file deletes single files only, not directories.")
    if not _GENERATED_NAME_RE.fullmatch(p.name):
        raise ValueError("Only temporary video files generated by instapuller can be deleted.")
    if not p.exists():
        return False
    p.unlink(missing_ok=True)
    return True
